// Mini App Gallery Service Worker
// Automatically generated by build.py - Do not edit directly
const CACHE_NAME = 'minigallery-e848b274c1';
const PRECACHE_ASSETS = [
  "./",
  "index.html",
  "style.css",
  "app.js",
  "manifest.webmanifest",
  "icons/icon.svg",
  "apps/addition/icon.svg",
  "apps/addition/index.html",
  "apps/addition/script.js",
  "apps/addition/style.css",
  "apps/boids/icon.svg",
  "apps/boids/index.html",
  "apps/count/icon.svg",
  "apps/count/index.html",
  "apps/dice/icon.svg",
  "apps/dice/index.html",
  "apps/letterfish/icon.svg",
  "apps/letterfish/index.html"
];

// Install: Precache all essential gallery assets and mini apps
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll(PRECACHE_ASSETS);
    }).then(() => self.skipWaiting())
  );
});

// Activate: Delete old cache versions and claim clients
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys.map((key) => {
          if (key !== CACHE_NAME && key.startsWith('minigallery-')) {
            return caches.delete(key);
          }
        })
      );
    }).then(() => self.clients.claim())
  );
});

// Fetch: Cache-first with Network fallback, updating cache on the fly
self.addEventListener('fetch', (event) => {
  const request = event.request;

  // Only handle GET requests
  if (request.method !== 'GET') return;

  event.respondWith(
    caches.open(CACHE_NAME).then(async (cache) => {
      // 1. Try exact match
      const cached = await cache.match(request, { ignoreSearch: true });
      if (cached) return cached;

      // 2. Handle directory paths matching index.html
      const url = new URL(request.url);
      if (url.pathname.endsWith('/')) {
        const indexMatch = await cache.match(url.pathname + 'index.html');
        if (indexMatch) return indexMatch;
      } else if (!url.pathname.split('/').pop().includes('.')) {
        const slashIndexMatch = await cache.match(url.pathname + '/index.html');
        if (slashIndexMatch) return slashIndexMatch;
      }

      // 3. Fallback to network
      try {
        const networkResponse = await fetch(request);
        if (networkResponse && networkResponse.status === 200 && networkResponse.type === 'basic') {
          cache.put(request, networkResponse.clone());
        }
        return networkResponse;
      } catch (err) {
        // If offline and requesting an HTML page, serve main index
        if (request.headers.get('accept') && request.headers.get('accept').includes('text/html')) {
          const fallback = await cache.match('index.html');
          if (fallback) return fallback;
        }
        throw err;
      }
    })
  );
});
